  virtual void Dump(...);                        // Dump计算图
  virtual void Clone(...);                       // 克隆Kernel

  // 辅助方法
  std::string &DumpGraph();                      // 获取计算图字符串
  virtual std::string &DisAssemble();            // 反汇编字节码
  KernelType KType() const;                      // 获取Kernel类型
