### 6.2 UB内存复用

```cpp
// Host侧分配xbuf
void AllocOutXBuf(NDObject *op) {
  // 尝试复用输入xbuf
  if (op->flags_ & F_LR && op->lhs_->flags_ & OBJ_FLAG_FREE_LHS) {
    op->xbuf_ = op->lhs_->xbuf_;
    return;
  }

  if (op->flags_ & F_RR && op->rhs_->flags_ & OBJ_FLAG_FREE_RHS) {
    op->xbuf_ = op->rhs_->xbuf_;
    return;
  }

  // 从空闲列表分配
  op->xbuf_ = free_xbuf_.Pop(op);
}
