// 在线Tuning
class OnlineTuner : public Tuner {
 public:
  void Tune(CubeOp *cube) override {
    // 尝试多种配置
    for (auto config : configs_) {
      auto result = RunWithConfig(cube, config);
      if (result.time < best_.time) {
        UpdateBest(result);
      }
    }

    // 应用最优配置
    ApplyBest(cube);
  }
};
