};

std::vector<TuneConfig> GenerateConfigs(uint64_t M, uint64_t N, uint64_t K) {
  std::vector<TuneConfig> configs;

  // M分块选项
  for (auto m_tile : {16, 32, 64, 128}) {
    if (m_tile > M) continue;

    // N分块选项
    for (auto n_tile : {16, 32, 64, 128}) {
      if (n_tile > N) continue;

